cuda_src = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
// Cooperative tiled direct 2D convolution.
// Each CTA computes an 8x8 spatial output tile for 4 output channels.
// The CTA cooperatively stages the strided input halo tile in shared memory,
// including zero padding for out-of-range input locations.
constexpr int TILE_H = 8;
constexpr int TILE_W = 8;
constexpr int COUT_TILE = 4;
constexpr int BLOCK_THREADS = TILE_H * TILE_W * COUT_TILE;
// Specialized register-blocked kernel for C_in=3, K=11, stride=4, pad=2.
// Each CTA computes an 8x8 spatial tile for 16 output channels.
// Each thread computes a 2x2 spatial block for 2 output channels (8 outputs),
// reusing staged input values across channels and staged weights across the
// 2x2 spatial block to raise the FMA-to-load ratio (register blocking).
constexpr int S_C_IN = 3;
constexpr int S_K = 11;
constexpr int S_STRIDE = 4;
constexpr int S_PAD = 2;
constexpr int S_COUT_TILE = 16;
constexpr int S_IN_H = (TILE_H - 1) * S_STRIDE + S_K; // 39
constexpr int S_IN_W = (TILE_W - 1) * S_STRIDE + S_K; // 39
constexpr int S_ROW = S_IN_W + 1;                     // 40, float4-friendly stride
constexpr int S_PLANE = S_IN_H * S_ROW;               // 1560
constexpr int S_IN_ELEMS = S_C_IN * S_PLANE;          // 4680
constexpr int S_W_ELEMS = S_COUT_TILE * S_C_IN * S_K * S_K; // 5808
constexpr int S_THREADS = 4 * 8 * 4;                  // 128
__global__ void __launch_bounds__(S_THREADS) conv2d_forward_kernel_s(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out)
{
    extern __shared__ float sh_mem[];
    float* sh_input = sh_mem;
    float* sh_weight = sh_mem + S_IN_ELEMS;
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out0 = blockIdx.y * S_COUT_TILE;
    const int n = blockIdx.z;
    const int in_h0 = h_out0 * S_STRIDE - S_PAD;
    const int in_w0 = w_out0 * S_STRIDE - S_PAD;
    const int tid = threadIdx.x + 4 * threadIdx.y + 32 * threadIdx.z;
    // Stage the strided input halo tile (zero padded, padded row stride).
    for (int i = tid; i < S_IN_ELEMS; i += S_THREADS) {
        const int c = i / S_PLANE;
        const int r = i - c * S_PLANE;
        const int y = r / S_ROW;
        const int x = r - y * S_ROW;
        const int h_in = in_h0 + y;
        const int w_in = in_w0 + x;
        float v = 0.0f;
        if (x < S_IN_W && h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            v = input[(((long long)n * S_C_IN + c) * H_in + h_in) * W_in + w_in];
        }
        sh_input[i] = v;
    }
    // Stage this CTA's weight slice (contiguous, coalesced).
    const float* w_base = weight + (long long)c_out0 * (S_C_IN * S_K * S_K);
    for (int i = tid; i < S_W_ELEMS; i += S_THREADS) {
        sh_weight[i] = w_base[i];
    }
    __syncthreads();
    const int tx = threadIdx.x; // 0..3 -> output cols tx*2, tx*2+1
    const int cg = threadIdx.y; // 0..7 -> output channels cg*2, cg*2+1
    const int ty = threadIdx.z; // 0..3 -> output rows ty*2, ty*2+1
    float s00a = 0.0f, s01a = 0.0f, s10a = 0.0f, s11a = 0.0f;
    float s00b = 0.0f, s01b = 0.0f, s10b = 0.0f, s11b = 0.0f;
    const int rbase = ty * 2 * S_STRIDE; // input row of first output row
    const int cbase = tx * 2 * S_STRIDE; // input col of first output col
    const float* wp = sh_weight + cg * 2 * (S_C_IN * S_K * S_K);
    #pragma unroll
    for (int c = 0; c < S_C_IN; ++c) {
        const float* plane = sh_input + c * S_PLANE;
        const float* w0 = wp + c * (S_K * S_K);
        const float* w1 = w0 + (S_C_IN * S_K * S_K);
        #pragma unroll
        for (int kh = 0; kh < S_K; ++kh) {
            const float4* row0 = reinterpret_cast<const float4*>(plane + (rbase + kh) * S_ROW + cbase);
            const float4* row1 = reinterpret_cast<const float4*>(plane + (rbase + kh + S_STRIDE) * S_ROW + cbase);
            const float a[16] = {row0[0].x, row0[0].y, row0[0].z, row0[0].w,
                                 row0[1].x, row0[1].y, row0[1].z, row0[1].w,
                                 row0[2].x, row0[2].y, row0[2].z, row0[2].w,
                                 row0[3].x, row0[3].y, row0[3].z, row0[3].w};
            const float b[16] = {row1[0].x, row1[0].y, row1[0].z, row1[0].w,
                                 row1[1].x, row1[1].y, row1[1].z, row1[1].w,
                                 row1[2].x, row1[2].y, row1[2].z, row1[2].w,
                                 row1[3].x, row1[3].y, row1[3].z, row1[3].w};
            const float* wr0 = w0 + kh * S_K;
            const float* wr1 = w1 + kh * S_K;
            #pragma unroll
            for (int kw = 0; kw < S_K; ++kw) {
                const float i00 = a[kw];
                const float i01 = a[kw + S_STRIDE];
                const float i10 = b[kw];
                const float i11 = b[kw + S_STRIDE];
                const float wv0 = wr0[kw];
                const float wv1 = wr1[kw];
                s00a += i00 * wv0; s01a += i01 * wv0; s10a += i10 * wv0; s11a += i11 * wv0;
                s00b += i00 * wv1; s01b += i01 * wv1; s10b += i10 * wv1; s11b += i11 * wv1;
            }
        }
    }
    const int h0 = h_out0 + ty * 2;
    const int w0o = w_out0 + tx * 2;
    const int cA = c_out0 + cg * 2;
    const int cB = cA + 1;
    const float bA = bias[cA];
    const float bB = bias[cB];
    float* out_base = output + ((long long)n * C_out) * H_out * W_out;
    if (h0 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s00a + bA; rowB[w0o] = s00b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s01a + bA; rowB[w0o + 1] = s01b + bB; }
    }
    if (h0 + 1 < H_out) {
        float* rowA = out_base + ((long long)cA * H_out + h0 + 1) * W_out;
        float* rowB = out_base + ((long long)cB * H_out + h0 + 1) * W_out;
        if (w0o < W_out)     { rowA[w0o] = s10a + bA; rowB[w0o] = s10b + bB; }
        if (w0o + 1 < W_out) { rowA[w0o + 1] = s11a + bA; rowB[w0o + 1] = s11b + bB; }
    }
}
__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int N, const int C_in, const int H_in, const int W_in,
    const int C_out, const int H_out, const int W_out,
    const int K, const int stride, const int pad)
{
    extern __shared__ float sh_input[];
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    const int tile_w = blockIdx.x % tiles_w;
    const int tile_h = blockIdx.x / tiles_w;
    const int h_out0 = tile_h * TILE_H;
    const int w_out0 = tile_w * TILE_W;
    const int c_out = blockIdx.y * COUT_TILE + threadIdx.z;
    const int n = blockIdx.z;
    const int h_out = h_out0 + threadIdx.y;
    const int w_out = w_out0 + threadIdx.x;
    const int in_h0 = h_out0 * stride - pad;
    const int in_w0 = w_out0 * stride - pad;
    const int in_h = (TILE_H - 1) * stride + K;
    const int in_w = (TILE_W - 1) * stride + K;
    const int plane_elems = in_h * in_w;
    const int tid = threadIdx.x + TILE_W * threadIdx.y + TILE_W * TILE_H * threadIdx.z;
    for (int i = tid; i < C_in * plane_elems; i += BLOCK_THREADS) {
        const int c = i / plane_elems;
        const int r = i - c * plane_elems;
        const int y = r / in_w;
        const int x = r - y * in_w;
        const int h_in = in_h0 + y;
        const int w_in = in_w0 + x;
        float v = 0.0f;
        if (h_in >= 0 && h_in < H_in && w_in >= 0 && w_in < W_in) {
            v = input[(((long long)n * C_in + c) * H_in + h_in) * W_in + w_in];
        }
        sh_input[i] = v;
    }
    __syncthreads();
    if (h_out >= H_out || w_out >= W_out || c_out >= C_out) return;
    const int y0 = threadIdx.y * stride;
    const int x0 = threadIdx.x * stride;
    float sum = 0.0f;
    for (int c = 0; c < C_in; ++c) {
        const float* sh_plane = sh_input + c * plane_elems;
        const float* w_ch = weight + (((long long)c_out * C_in + c) * K) * K;
        #pragma unroll 4
        for (int kh = 0; kh < K; ++kh) {
            const float* sh_row = sh_plane + (y0 + kh) * in_w;
            const float* w_row = w_ch + kh * K;
            #pragma unroll 4
            for (int kw = 0; kw < K; ++kw) {
                sum += sh_row[x0 + kw] * w_row[kw];
            }
        }
    }
    output[(((long long)n * C_out + c_out) * H_out + h_out) * W_out + w_out] = sum + bias[c_out];
}
torch::Tensor conv2d_forward(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                             int64_t stride, int64_t pad)
{
    TORCH_CHECK(input.is_cuda() && weight.is_cuda() && bias.is_cuda(),
                "All tensors must be on CUDA");
    TORCH_CHECK(input.scalar_type() == torch::kFloat32 &&
                weight.scalar_type() == torch::kFloat32 &&
                bias.scalar_type() == torch::kFloat32,
                "Only float32 tensors are supported");
    TORCH_CHECK(input.dim() == 4 && weight.dim() == 4 && bias.dim() == 1,
                "Bad tensor ranks");
    auto input_c = input.contiguous();
    auto weight_c = weight.contiguous();
    auto bias_c = bias.contiguous();
    const int N     = input_c.size(0);
    const int C_in  = input_c.size(1);
    const int H_in  = input_c.size(2);
    const int W_in  = input_c.size(3);
    const int C_out = weight_c.size(0);
    const int K     = weight_c.size(2);
    TORCH_CHECK(weight_c.size(1) == C_in && weight_c.size(3) == K &&
                bias_c.size(0) == C_out, "Shape mismatch");
    const int H_out = (H_in + 2 * (int)pad - K) / (int)stride + 1;
    const int W_out = (W_in + 2 * (int)pad - K) / (int)stride + 1;
    TORCH_CHECK(H_out > 0 && W_out > 0, "Invalid output size");
    auto output = torch::empty({N, C_out, H_out, W_out}, input_c.options());
    const int tiles_h = (H_out + TILE_H - 1) / TILE_H;
    const int tiles_w = (W_out + TILE_W - 1) / TILE_W;
    static int max_dynamic_smem = -1;
    if (max_dynamic_smem < 0) {
        int dev = 0;
        cudaGetDevice(&dev);
        cudaDeviceProp prop;
        cudaGetDeviceProperties(&prop, dev);
        max_dynamic_smem = (int)prop.sharedMemPerBlockOptin;
        cudaFuncSetAttribute(reinterpret_cast<const void*>(conv2d_forward_kernel),
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             max_dynamic_smem);
        cudaFuncSetAttribute(reinterpret_cast<const void*>(conv2d_forward_kernel_s),
                             cudaFuncAttributeMaxDynamicSharedMemorySize,
                             max_dynamic_smem);
    }
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    if (C_in == S_C_IN && K == S_K && (int)stride == S_STRIDE && (int)pad == S_PAD &&
        C_out % S_COUT_TILE == 0) {
        const size_t smem_bytes = (size_t)(S_IN_ELEMS + S_W_ELEMS) * sizeof(float);
        TORCH_CHECK(smem_bytes <= (size_t)max_dynamic_smem, "Shared memory tile too large");
        dim3 block(4, 8, 4);
        dim3 grid(tiles_w * tiles_h, C_out / S_COUT_TILE, N);
        conv2d_forward_kernel_s<<<grid, block, smem_bytes, stream>>>(
            input_c.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            output.data_ptr<float>(),
            N, H_in, W_in,
            C_out, H_out, W_out);
    } else {
        const int in_h = (TILE_H - 1) * (int)stride + K;
        const int in_w = (TILE_W - 1) * (int)stride + K;
        const size_t smem_bytes = (size_t)C_in * in_h * in_w * sizeof(float);
        TORCH_CHECK(smem_bytes <= (size_t)max_dynamic_smem, "Shared memory tile too large");
        dim3 block(TILE_W, TILE_H, COUT_TILE);
        dim3 grid(tiles_w * tiles_h, (C_out + COUT_TILE - 1) / COUT_TILE, N);
        conv2d_forward_kernel<<<grid, block, smem_bytes, stream>>>(
            input_c.data_ptr<float>(),
            weight_c.data_ptr<float>(),
            bias_c.data_ptr<float>(),
            output.data_ptr<float>(),
            N, C_in, H_in, W_in,
            C_out, H_out, W_out,
            K, (int)stride, (int)pad);
    }
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}
